-- ESP32 Bluetooth RGB LED Controller driver circuit (slug 24).
-- Replaces the GPIO-sourced common-cathode LED with a 5 V common-anode LED and PN2222A switches.
-- Does not change other projects. Leaves slug 24 unpublished.

insert into public.components (name, category, description, slug)
values
  ($rgbdriver$Common-anode RGB LED$rgbdriver$, $rgbdriver$modules$rgbdriver$, $rgbdriver$5 mm common-anode RGB LED in the SparkFun COM-10818 family. SparkFun says this part uses the common-cathode datasheet values and shares an anode. Leads pointing down, longest lead second from the left: red cathode, common anode, green cathode, blue cathode. At 20 mA the typical forward voltage is 2.0 V red and 3.2 V green and blue; green and blue may reach 3.4 V. This row is not a common-cathode LED and not an addressable pixel.$rgbdriver$, $rgbdriver$rgb-led-ca$rgbdriver$),
  ($rgbdriver$PN2222A transistor$rgbdriver$, $rgbdriver$modules$rgbdriver$, $rgbdriver$PN2222A NPN transistor in TO-92. Flat face toward you, leads down: emitter, base, collector. A metal-can 2N2222 has a different pin order. Used as a low-side switch.$rgbdriver$, $rgbdriver$pn2222a$rgbdriver$)
on conflict (slug) do update
set
  name = excluded.name,
  category = excluded.category,
  description = excluded.description;

insert into public.component_capabilities (component_id, capability, value)
select c.id, v.capability, v.value
from (
  values
    ('rgb-led-ca', 'function', 'rgb_led'),
    ('rgb-led-ca', 'physical_form', 'common_anode'),
    ('pn2222a', 'function', 'npn_transistor'),
    ('pn2222a', 'physical_form', 'to-92')
) as v(slug, capability, value)
join public.components c on c.slug = v.slug
on conflict (component_id, capability, value) do update
set value = excluded.value;

update public.projects
set
  description = $rgbdriver$Mix a red, green, and blue LED from a phone over Bluetooth Low Energy.$rgbdriver$,
  overview = $rgbdriver$Build a breadboard RGB light on an ESP32 DevKit. The LED takes power from the DevKit 5 V pin through resistors and PN2222A switches. Three PWM pins set the colour, and Nordic nRF Connect writes the colour and brightness over BLE. The sketch does not use Bluetooth Classic.$rgbdriver$,
  duration_label = $rgbdriver$3 hrs$rgbdriver$,
  learning_objectives = array[$rgbdriver$Switch a common-anode RGB LED from the DevKit 5 V pin with a PN2222A and a 220 Ω resistor on each colour$rgbdriver$, $rgbdriver$Use LEDC PWM on GPIO25, GPIO26, and GPIO27 to drive those transistor bases through 1 kΩ$rgbdriver$, $rgbdriver$Advertise a BLE GATT service that accepts colour and brightness writes$rgbdriver$, $rgbdriver$Connect with nRF Connect for Mobile and compare the LED with the Serial Monitor$rgbdriver$],
  is_published = false
where slug = '24' and title = 'ESP32 Bluetooth RGB LED Controller';

delete from public.project_components
where project_id = (select id from public.projects where slug = '24' and title = 'ESP32 Bluetooth RGB LED Controller');

