  ((select id from public.projects where slug = '24'), (select id from public.components where slug = 'resistor-220'), 3, 4),
  ((select id from public.projects where slug = '24'), (select id from public.components where slug = 'resistor-1k'), 3, 5),
  ((select id from public.projects where slug = '24'), (select id from public.components where slug = 'breadboard'), 1, 6),
  ((select id from public.projects where slug = '24'), (select id from public.components where slug = 'jumper-male-female'), 5, 7),
  ((select id from public.projects where slug = '24'), (select id from public.components where slug = 'usb-data-cable'), 1, 8),
  ((select id from public.projects where slug = '24'), (select id from public.components where slug = 'usb-power-source'), 1, 9);

