delete from public.project_steps
where project_id = (select id from public.projects where slug = '24' and title = 'ESP32 Bluetooth RGB LED Controller');

insert into public.project_steps (
  project_id, sort_order, stage_sort_order, stage_title, title, description, tip, blocks
)
select p.id, v.sort_order, v.stage_sort_order, v.stage_title, v.title, v.description, v.tip, v.blocks::jsonb
from public.projects p
cross join (
  values
  (0, 0, $rgbdriver$Introduction$rgbdriver$, $rgbdriver$What the finished controller does$rgbdriver$, $rgbdriver$A phone sets the colour and brightness of one RGB LED over Bluetooth Low Energy.$rgbdriver$, null, $rgbdriver$[{"type":"image","imageKey":"esp32BleRgb","caption":"The finished controller is an ESP32-DevKitC V4 above a breadboard, with one common-anode RGB LED, three PN2222A transistors, and six resistors, powered from USB. The wiring diagram is the connection reference."},{"type":"text","heading":"What you are building","body":"The ESP32 DevKit switches one 5 mm common-anode RGB LED. The DevKit 5V pin feeds the common anode. Each colour cathode returns to ground through a 220 Ω resistor and a PN2222A. GPIO25, GPIO26, and GPIO27 drive the transistor bases through 1 kΩ, and a high PWM duty turns that colour on. After upload, the LED starts red at 30 percent brightness and the board advertises the BLE name Solderi RGB. Nordic nRF Connect writes a new colour and a new brightness. Nothing is sent to a cloud account, and the sketch does not join Wi-Fi."},{"type":"expected","heading":"What done looks like","body":"The Serial Monitor at 115200 baud prints the power-on line and “Advertising as Solderi RGB.” nRF Connect connects to that name. Writing 0,0,255 turns the light blue. Writing 100 to the brightness characteristic makes it as bright as this circuit allows. Writing 0 turns it off without disconnecting Bluetooth."}]$rgbdriver$),
  (1, 0, $rgbdriver$Introduction$rgbdriver$, $rgbdriver$What you will learn$rgbdriver$, $rgbdriver$This build is one LED, three transistors, six resistors, PWM, and one BLE service.$rgbdriver$, null, $rgbdriver$[{"type":"text","heading":"Skills in this project","body":"You will identify ESP32 5V, GND, IO25, IO26, and IO27, the four leads of a common-anode RGB LED, and the emitter, base, and collector of a PN2222A. You will see why green and blue need the 5 V rail, and why each colour still has a 220 Ω resistor. You will upload one complete sketch, then use nRF Connect to write colour text such as 255,80,0 and a brightness from 0 to 100."},{"type":"text","heading":"What this project does not use","body":"It does not use Bluetooth Classic, a serial-port app, or BluetoothSerial.h. It does not use a common-cathode LED wired straight to a GPIO, a WS2812 addressable pixel, or an ESP8266. Those parts do not follow this pin map or this phone procedure. iOS can talk to BLE GATT devices, which is what nRF Connect does. This repository has not paired a phone to the board."}]$rgbdriver$),
  (2, 0, $rgbdriver$Introduction$rgbdriver$, $rgbdriver$How the hardware and the phone work together$rgbdriver$, $rgbdriver$USB powers the DevKit. The 5V pin feeds the LED. The GPIO pins only switch the transistors. The phone writes two BLE characteristics.$rgbdriver$, null, $rgbdriver$[{"type":"text","heading":"The electrical path","body":"USB power feeds the ESP32 DevKit. Do not also connect a second supply to the 5V or 3V3 header. With only USB connected, the DevKitC V4 5V header is the USB 5 V rail after the board’s series diode, so it can feed the LED. Current leaves that pin, enters the common anode, leaves through one colour cathode, passes through that colour’s 220 Ω resistor and PN2222A, and returns to GND. A GPIO high turns its transistor on. A higher PWM duty keeps it on for more of each cycle, so that colour looks brighter. The GPIO does not carry the LED current."},{"type":"text","heading":"The Bluetooth path","body":"The sketch starts a BLE server named Solderi RGB. The service UUID is 8c4a2e10-1b6d-4f3a-9e72-5d0c8a1b6e24. One characteristic takes the colour. The next takes brightness. nRF Connect is the central. It scans, connects, and writes those characteristics. The LED holds the last accepted colour if the phone disconnects, and the board starts advertising again."}]$rgbdriver$),
  (3, 0, $rgbdriver$Introduction$rgbdriver$, $rgbdriver$What a successful build should do$rgbdriver$, $rgbdriver$Success is a visible colour change from a BLE write, plus a Serial line that matches it.$rgbdriver$, null, $rgbdriver$[{"type":"text","heading":"Check these behaviours","body":"Before any phone connects, the LED is red and dim. Serial prints “Power-on colour is red at 30 percent brightness.” and then “Advertising as Solderi RGB.” After a connection it prints “Phone connected.” A colour write of 0,255,0 prints “Colour 0,255,0” and the LED becomes green. A brightness write of 0 prints “Brightness 0” and the LED goes dark. A rejected write prints “Colour rejected:” or “Brightness rejected:” and leaves the previous light unchanged."},{"type":"warning","body":"This repository has not run the sketch on a physical ESP32 and has not connected nRF Connect to a board. Treat the Serial lines and colours below as the behaviour the code is written to produce, and compare them with what your board and phone actually do."}]$rgbdriver$),
  (4, 1, $rgbdriver$Hardware preparation$rgbdriver$, $rgbdriver$Identify every required component$rgbdriver$, $rgbdriver$Every physical item in this build is on the BOM. The phone is the controller app, not a wired part.$rgbdriver$, $rgbdriver$A phone with Bluetooth Low Energy is required to change the colour. It is not a BOM line.$rgbdriver$, $rgbdriver$[{"type":"components","heading":"Required parts","items":[{"id":"esp32","name":"ESP32 DevKit","illustrationId":"esp32","owned":false,"quantity":1},{"id":"rgb-led-ca","name":"Common-anode RGB LED","illustrationId":"led","owned":false,"quantity":1},{"id":"pn2222a","name":"PN2222A transistor","illustrationId":"generic-module","owned":false,"quantity":3},{"id":"resistor-220","name":"220 Ω resistor","illustrationId":"resistor","owned":false,"quantity":3},{"id":"resistor-1k","name":"1 kΩ resistor","illustrationId":"resistor","owned":false,"quantity":3},{"id":"breadboard","name":"Breadboard","illustrationId":"breadboard","owned":false,"quantity":1},{"id":"jumper-male-female","name":"Male-to-female jumper wires","illustrationId":"jumper-wires","owned":false,"quantity":5},{"id":"usb-data-cable","name":"USB data cable","illustrationId":"usb-cable","owned":false,"quantity":1},{"id":"usb-power-source","name":"USB power source","illustrationId":"generic-module","owned":false,"quantity":1}]},{"type":"text","heading":"What each part is for","body":"The ESP32 DevKit is the controller and the BLE peripheral. The common-anode RGB LED is the only lamp. Three PN2222A transistors switch the colours. Three 220 Ω resistors limit the LED current. Three 1 kΩ resistors limit the base current. The breadboard holds the LED, the transistors, and the resistors. Five male-to-female jumpers reach 5V, GND, IO25, IO26, and IO27. The USB data cable carries power and the upload. The USB power source is the computer port while you program, or a USB charger after the sketch is on the board."},{"type":"expected","heading":"Check","body":"You can point to one ESP32 DevKit, one four-lead RGB LED sold as common anode, three PN2222A transistors, three 220 Ω resistors, three 1 kΩ resistors, one breadboard, five male-to-female jumpers, one data-capable USB cable, and a USB port or charger."}]$rgbdriver$),
  (5, 1, $rgbdriver$Hardware preparation$rgbdriver$, $rgbdriver$Confirm the ESP32 DevKit labels$rgbdriver$, $rgbdriver$This guide uses 5V, GND, IO25, IO26, and IO27. Stop if your silkscreen does not show those names.$rgbdriver$, $rgbdriver$Espressif’s ESP32-DevKitC V4 user guide lists a Micro-USB socket. The catalogue row does not fix the socket on every board sold as a DevKit.$rgbdriver$, $rgbdriver$[{"type":"text","heading":"What to look for","body":"Solderi’s ESP32 DevKit row is a 3.3 V board programmed with the Arduino-ESP32 package. This project’s wiring uses 5V, GND, IO25, IO26, and IO27. Those GPIO numbers are not the strapping pins 0, 2, 12, or 15, and they are not the input-only pins 34 to 39. Espressif’s ESP32-WROOM-32 module includes Bluetooth Low Energy. The sketch uses the Arduino-ESP32 BLE library, which speaks BLE GATT. It does not open a Bluetooth Classic serial port. Each GPIO only sources about 2.6 mA into a 1 kΩ base resistor. The ESP32 datasheet allows a much higher pin current, and that current falls as the high level sags, so the LED current stays on the 5V pin."},{"type":"text","heading":"USB and headers","body":"Espressif’s ESP32-DevKitC V4 uses USB-A to Micro-B and male headers. Confirm the silkscreen shows 5V, GND, IO25, IO26, and IO27 before you continue. Use a data cable that fits the socket. A charge-only cable can light the board and still never appear as a serial port. Leave the DevKit beside the breadboard. Do not bend its header pins to press it into the breadboard."},{"type":"warning","body":"If those labels are missing, stop. Do not move the wires onto an ESP32-CAM or an ESP32-S2. An S2 module does not provide this project’s Bluetooth radio. Power the board from USB only. The 5V header then feeds the LED. Do not connect a second supply to the 5V pin or the 3V3 pin while USB is plugged in."}]$rgbdriver$),
  (6, 1, $rgbdriver$Hardware preparation$rgbdriver$, $rgbdriver$Confirm the LED is common anode$rgbdriver$, $rgbdriver$The longest lead goes to the 5 V rail. A common-cathode LED is a different circuit.$rgbdriver$, $rgbdriver$Lead length marks the common pin on this family. The part must be sold as common anode.$rgbdriver$, $rgbdriver$[{"type":"text","heading":"What to look for","body":"Use a 5 mm common-anode RGB LED in the SparkFun COM-10818 family. SparkFun says the electrical values match the common-cathode datasheet and the shared lead is the anode. That datasheet, Young Sun YSL-R596CR3G4B5C-C10, lists pin 1 red, pin 2 the common lead, pin 3 green, and pin 4 blue, and it says the common lead is the longest. Hold the LED with the leads pointing down and the longest lead second from the left. Left to right the leads are: red cathode, common anode, green cathode, blue cathode. At 20 mA the typical forward voltage is 2.0 V for red and 3.2 V for green and blue, and green and blue may reach 3.4 V. A common-cathode part is a different circuit."},{"type":"warning","body":"Do not substitute a common-cathode LED, and do not tie the common pin to GND to try one. Driving these green and blue dice from a 3.3 V GPIO is the circuit this project replaces: at a 3.4 V drop they do not conduct. An addressable LED such as a WS2812 uses one data pin and is a different project."},{"type":"expected","heading":"Check","body":"You can point to lead 1 red, lead 2 the longest anode, lead 3 green, and lead 4 blue. If your datasheet numbers those leads differently, stop and do not guess. After upload, the power-on colour is red. Only the cathode on the red 220 Ω resistor should light. If another lead lights, that lead is the red cathode, so move the red 220 Ω resistor to it before you trust green and blue."}]$rgbdriver$),
  (7, 1, $rgbdriver$Hardware preparation$rgbdriver$, $rgbdriver$Read the resistors and the transistor leads$rgbdriver$, $rgbdriver$Each colour uses one 220 Ω LED resistor, one 1 kΩ base resistor, and one PN2222A.$rgbdriver$, $rgbdriver$220 Ω is red, red, brown, gold. 1 kΩ is brown, black, red, gold.$rgbdriver$, $rgbdriver$[{"type":"text","heading":"Why these values","body":"Green and blue can drop 3.4 V. A 3.3 V GPIO cannot light that die, even with no resistor, so the LED current comes from the 5V pin. Espressif’s DevKitC V4 schematic places a BAT760 diode between USB VBUS and that pin. On a USB port near 5 V the pin is about 4.7 V. Allow about 0.2 V across a saturated PN2222A. Green or blue at 3.4 V through 220 Ω is then about (4.7 − 3.4 − 0.2) / 220, about 5 mA. At the typical 3.2 V it is about 6 mA. Red at 2.0 V from a 5.0 V pin is about (5.0 − 2.0 − 0.2) / 220, about 13 mA, and it stays under the LED’s 20 mA maximum even if red is 1.8 V. The same 220 Ω fits every colour. If a weak USB port is only 4.4 V and the diode drops 0.5 V, the pin can fall to about 3.9 V and a 3.4 V die has about 1 mA left. That is still current. The same die on a 3.3 V GPIO has none. Each base resistor is 1 kΩ, so the base current is about (3.3 − 0.7) / 1000, about 2.6 mA. That saturates the transistor at these LED currents, and three pins together are about 8 mA, inside the ESP32 pin budget. Do not remove the 220 Ω resistors."},{"type":"text","heading":"Transistor leads","body":"Use a TO-92 PN2222A. Flat face toward you and leads pointing down, the order is emitter, base, collector. The diagram labels these Q red, Q green, and Q blue. A metal-can 2N2222 has a different pin order. If that is the part in your hand, stop and read its datasheet before you insert it."},{"type":"expected","heading":"Check","body":"Set three 220 Ω resistors aside, one for each colour, and three 1 kΩ resistors aside for the three bases. Each transistor’s flat face is identified, and you can point to emitter, base, and collector."}]$rgbdriver$),
  (8, 2, $rgbdriver$Wiring$rgbdriver$, $rgbdriver$Connect 5 V, the anode, and the emitters$rgbdriver$, $rgbdriver$The 5V pin feeds the common anode. All three emitters share the ground rail.$rgbdriver$, $rgbdriver$USB is the only power source. The 5V header is an output for the LED, not a second supply.$rgbdriver$, $rgbdriver$[{"type":"text","heading":"Connection sequence","body":"Seat the RGB LED so each lead has its own row. Seat each PN2222A with the flat face toward you: emitter, base, collector in three neighbouring rows. Jumper ESP32 5V to the red breadboard rail, and jumper that rail to the longest LED lead, the common anode. Jumper ESP32 GND to the blue ground rail, and connect each transistor emitter to that rail. Leave the 3V3 header empty. Leave USB unplugged. The diagram names the transistors Q red, Q green, and Q blue."},{"type":"wiring","heading":"Supply and ground","connections":[{"fromComponent":"ESP32 DevKit","fromPin":"5V","toComponent":"Breadboard","toPin":"5V rail","signal":"power"},{"fromComponent":"Breadboard","fromPin":"5V rail","toComponent":"RGB LED","toPin":"Anode","signal":"power"},{"fromComponent":"ESP32 DevKit","fromPin":"GND","toComponent":"Breadboard","toPin":"GND rail","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Q red","toPin":"Emitter","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Q green","toPin":"Emitter","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Q blue","toPin":"Emitter","signal":"ground"}]},{"type":"connections","summary":"5V to the anode · emitters to GND","rows":[{"fromComponent":"ESP32 DevKit","fromPin":"5V","toComponent":"Breadboard","toPin":"5V rail","signal":"power"},{"fromComponent":"Breadboard","fromPin":"5V rail","toComponent":"RGB LED","toPin":"Anode","signal":"power"},{"fromComponent":"ESP32 DevKit","fromPin":"GND","toComponent":"Breadboard","toPin":"GND rail","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Q red","toPin":"Emitter","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Q green","toPin":"Emitter","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Q blue","toPin":"Emitter","signal":"ground"}]},{"type":"warning","body":"Do not connect a GPIO to the 5V rail or to a colour cathode. The GPIO only reaches a 1 kΩ resistor. Do not connect another supply to the 5V pin while the USB cable is the board’s power source."}]$rgbdriver$),
  (9, 2, $rgbdriver$Wiring$rgbdriver$, $rgbdriver$Connect red, green, and blue$rgbdriver$, $rgbdriver$Each colour is GPIO, 1 kΩ, base, collector, 220 Ω, cathode. The colours are not interchangeable.$rgbdriver$, $rgbdriver$IO25 is red, IO26 is green, and IO27 is blue. The sketch uses those same numbers.$rgbdriver$, $rgbdriver$[{"type":"text","heading":"Connection sequence","body":"For red, jumper IO25 to leg 1 of the resistor labelled 1k red. Put leg 2 in the base row of Q red. Put the collector of Q red in the same row as leg 1 of the resistor labelled 220 red. Put leg 2 of that resistor in the red cathode row. Repeat with IO26, 1k green, Q green, 220 green, and the green cathode. Repeat with IO27, 1k blue, Q blue, 220 blue, and the blue cathode. The five male-to-female jumpers are 5V, GND, IO25, IO26, and IO27. The other links are component leads in shared breadboard rows. The diagram still draws every electrical segment."},{"type":"wiring","heading":"Colour channels","connections":[{"fromComponent":"ESP32 DevKit","fromPin":"IO25","toComponent":"1k red","toPin":"leg 1","signal":"signal"},{"fromComponent":"1k red","fromPin":"leg 2","toComponent":"Q red","toPin":"Base","signal":"signal"},{"fromComponent":"Q red","fromPin":"Collector","toComponent":"220 red","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 red","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Red","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO26","toComponent":"1k green","toPin":"leg 1","signal":"signal"},{"fromComponent":"1k green","fromPin":"leg 2","toComponent":"Q green","toPin":"Base","signal":"signal"},{"fromComponent":"Q green","fromPin":"Collector","toComponent":"220 green","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 green","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Green","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO27","toComponent":"1k blue","toPin":"leg 1","signal":"signal"},{"fromComponent":"1k blue","fromPin":"leg 2","toComponent":"Q blue","toPin":"Base","signal":"signal"},{"fromComponent":"Q blue","fromPin":"Collector","toComponent":"220 blue","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 blue","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Blue","signal":"signal"}]},{"type":"connections","summary":"IO25 red · IO26 green · IO27 blue","rows":[{"fromComponent":"ESP32 DevKit","fromPin":"IO25","toComponent":"1k red","toPin":"leg 1","signal":"signal"},{"fromComponent":"1k red","fromPin":"leg 2","toComponent":"Q red","toPin":"Base","signal":"signal"},{"fromComponent":"Q red","fromPin":"Collector","toComponent":"220 red","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 red","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Red","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO26","toComponent":"1k green","toPin":"leg 1","signal":"signal"},{"fromComponent":"1k green","fromPin":"leg 2","toComponent":"Q green","toPin":"Base","signal":"signal"},{"fromComponent":"Q green","fromPin":"Collector","toComponent":"220 green","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 green","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Green","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO27","toComponent":"1k blue","toPin":"leg 1","signal":"signal"},{"fromComponent":"1k blue","fromPin":"leg 2","toComponent":"Q blue","toPin":"Base","signal":"signal"},{"fromComponent":"Q blue","fromPin":"Collector","toComponent":"220 blue","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 blue","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Blue","signal":"signal"}]}]$rgbdriver$),
  (10, 2, $rgbdriver$Wiring$rgbdriver$, $rgbdriver$Read the complete wiring table$rgbdriver$, $rgbdriver$These eighteen connections are the whole circuit. Five of them are jumpers.$rgbdriver$, null, $rgbdriver$[{"type":"wiring","heading":"Complete wiring diagram","connections":[{"fromComponent":"ESP32 DevKit","fromPin":"5V","toComponent":"Breadboard","toPin":"5V rail","signal":"power"},{"fromComponent":"Breadboard","fromPin":"5V rail","toComponent":"RGB LED","toPin":"Anode","signal":"power"},{"fromComponent":"ESP32 DevKit","fromPin":"GND","toComponent":"Breadboard","toPin":"GND rail","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Q red","toPin":"Emitter","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Q green","toPin":"Emitter","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Q blue","toPin":"Emitter","signal":"ground"},{"fromComponent":"ESP32 DevKit","fromPin":"IO25","toComponent":"1k red","toPin":"leg 1","signal":"signal"},{"fromComponent":"1k red","fromPin":"leg 2","toComponent":"Q red","toPin":"Base","signal":"signal"},{"fromComponent":"Q red","fromPin":"Collector","toComponent":"220 red","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 red","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Red","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO26","toComponent":"1k green","toPin":"leg 1","signal":"signal"},{"fromComponent":"1k green","fromPin":"leg 2","toComponent":"Q green","toPin":"Base","signal":"signal"},{"fromComponent":"Q green","fromPin":"Collector","toComponent":"220 green","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 green","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Green","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO27","toComponent":"1k blue","toPin":"leg 1","signal":"signal"},{"fromComponent":"1k blue","fromPin":"leg 2","toComponent":"Q blue","toPin":"Base","signal":"signal"},{"fromComponent":"Q blue","fromPin":"Collector","toComponent":"220 blue","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 blue","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Blue","signal":"signal"}]},{"type":"connections","heading":"Every electrical connection","summary":"5V to the anode · IO25 red · IO26 green · IO27 blue · emitters to GND","rows":[{"fromComponent":"ESP32 DevKit","fromPin":"5V","toComponent":"Breadboard","toPin":"5V rail","signal":"power"},{"fromComponent":"Breadboard","fromPin":"5V rail","toComponent":"RGB LED","toPin":"Anode","signal":"power"},{"fromComponent":"ESP32 DevKit","fromPin":"GND","toComponent":"Breadboard","toPin":"GND rail","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Q red","toPin":"Emitter","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Q green","toPin":"Emitter","signal":"ground"},{"fromComponent":"Breadboard","fromPin":"GND rail","toComponent":"Q blue","toPin":"Emitter","signal":"ground"},{"fromComponent":"ESP32 DevKit","fromPin":"IO25","toComponent":"1k red","toPin":"leg 1","signal":"signal"},{"fromComponent":"1k red","fromPin":"leg 2","toComponent":"Q red","toPin":"Base","signal":"signal"},{"fromComponent":"Q red","fromPin":"Collector","toComponent":"220 red","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 red","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Red","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO26","toComponent":"1k green","toPin":"leg 1","signal":"signal"},{"fromComponent":"1k green","fromPin":"leg 2","toComponent":"Q green","toPin":"Base","signal":"signal"},{"fromComponent":"Q green","fromPin":"Collector","toComponent":"220 green","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 green","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Green","signal":"signal"},{"fromComponent":"ESP32 DevKit","fromPin":"IO27","toComponent":"1k blue","toPin":"leg 1","signal":"signal"},{"fromComponent":"1k blue","fromPin":"leg 2","toComponent":"Q blue","toPin":"Base","signal":"signal"},{"fromComponent":"Q blue","fromPin":"Collector","toComponent":"220 blue","toPin":"leg 1","signal":"signal"},{"fromComponent":"220 blue","fromPin":"leg 2","toComponent":"RGB LED","toPin":"Blue","signal":"signal"}]},{"type":"text","heading":"How this matches the sketch","body":"The firmware sets RED_PIN to 25, GREEN_PIN to 26, and BLUE_PIN to 27. Those headers drive the bases. A higher duty still means a brighter colour, because a high output turns the PN2222A on. The diagram draws eighteen segments: two for the 5 V path, four for ground, and four for each colour. That is three PWM pins. Each colour still has its 220 Ω resistor between the collector and the cathode."}]$rgbdriver$),
  (11, 2, $rgbdriver$Wiring$rgbdriver$, $rgbdriver$Check the circuit before you apply power$rgbdriver$, $rgbdriver$Count the paths, then connect USB. Do not add a second power source.$rgbdriver$, $rgbdriver$USB is the only supply. The 5V header feeds the LED from that same USB rail.$rgbdriver$, $rgbdriver$[{"type":"test","heading":"What to verify","body":"The common anode reaches only the 5V rail, and that rail reaches only the ESP32 5V pin. Each emitter reaches only the GND rail, and that rail reaches only ESP32 GND. IO25 reaches only 1k red, that resistor reaches only the red base, the red collector reaches only 220 red, and that resistor reaches only the red cathode. Green follows IO26, and blue follows IO27. No cathode shares a row with the anode. The 3V3 header is empty. No GPIO touches 5V. USB is still unplugged."},{"type":"text","heading":"Then apply power","body":"Plug the data cable into the DevKit and into the computer USB port you will use for upload. On an ESP32-DevKitC V4, the power LED lights when USB power is present. If you later move the board to a USB charger, unplug the computer first so only one power source is connected."},{"type":"expected","heading":"Expected result","body":"The board’s power LED is on. The RGB LED stays off until the sketch runs. The LED package does not get hot."}]$rgbdriver$),
  (12, 3, $rgbdriver$Development environment$rgbdriver$, $rgbdriver$Install the ESP32 board package$rgbdriver$, $rgbdriver$BLE and LEDC come from Espressif’s ESP32 package. They are not separate Library Manager installs.$rgbdriver$, $rgbdriver$Use the stable package URL. The development URL is a different package.$rgbdriver$, $rgbdriver$[{"type":"text","heading":"What to do","body":"Install the current Arduino IDE from arduino.cc. Open File > Preferences, or Arduino IDE > Settings. In Additional boards manager URLs, add https://espressif.github.io/arduino-esp32/package_esp32_index.json and click OK. Open Tools > Board > Boards Manager, search for esp32 by Espressif Systems, and install the esp32 platform. This sketch uses ledcAttach and the BLE classes from that platform’s 3.x API."},{"type":"expected","heading":"What you should see","body":"Boards Manager shows the esp32 package as installed. Tools > Board contains an ESP32 Arduino group. You do not install a Bluetooth library from Library Manager for this sketch."}]$rgbdriver$),
  (13, 3, $rgbdriver$Development environment$rgbdriver$, $rgbdriver$Select the board and the serial port$rgbdriver$, $rgbdriver$Choose ESP32 Dev Module, then the port that appears when the data cable is plugged in.$rgbdriver$, $rgbdriver$If the port never appears, try another data cable before you change any wiring.$rgbdriver$, $rgbdriver$[{"type":"text","heading":"Board and port","body":"Open Tools > Board > ESP32 Arduino and choose ESP32 Dev Module. Do not choose ESP32-S2, ESP32-C3, or ESP32-CAM. Plug in the data cable. Open Tools > Port and select the new port. On Windows it is a COM port. On macOS it is a /dev/cu.usbserial or /dev/cu.SLAB port. Unplug the cable and open the menu again: the correct port is the one that disappears."},{"type":"troubleshooting","heading":"If the port is missing","items":[{"problem":"No new port appears","solution":"The cable may be charge-only, or it may be in the wrong socket. Use a data cable that fits the DevKit. Then reopen Tools > Port."},{"problem":"Several ports are listed","solution":"Unplug the DevKit, see which port vanishes, and select that one after reconnecting."}]}]$rgbdriver$),
  (14, 3, $rgbdriver$Development environment$rgbdriver$, $rgbdriver$Set the Serial Monitor to 115200 baud$rgbdriver$, $rgbdriver$The sketch calls Serial.begin(115200). A mismatched baud rate looks like garbage text.$rgbdriver$, null, $rgbdriver$[{"type":"text","heading":"What to do","body":"Open Tools > Serial Monitor. Choose 115200 baud. Leave the line ending on Newline. The colour and brightness lines appear only after the sketch is uploaded."},{"type":"expected","heading":"What you should observe","body":"The monitor is open on the same port you selected for upload, and the baud value reads 115200."}]$rgbdriver$),
  (15, 4, $rgbdriver$Firmware$rgbdriver$, $rgbdriver$See how PWM sets each colour$rgbdriver$, $rgbdriver$Excerpt only. This is not a complete sketch. Brightness scales the three channel values before LEDC writes them.$rgbdriver$, $rgbdriver$A duty of 0 is off. A duty of 255 is the brightest this 8-bit setup can make that channel, before the brightness percentage.$rgbdriver$, $rgbdriver$[{"type":"text","heading":"What this code does","body":"channelDuty multiplies the colour byte by the brightness percentage and divides by 100. applyColour writes that duty to GPIO25, GPIO26, and GPIO27 with ledcWrite. Each GPIO drives a PN2222A base, so a higher duty turns that colour on for longer. The phone does not send PWM numbers. It sends a colour and a percentage, and this function turns them into duties."},{"type":"code","language":"Arduino","filename":"esp32_ble_rgb_controller.ino","libraries":["BLE (ESP32 Arduino core)","LEDC (ESP32 Arduino core)"],"code":"int channelDuty(int channel) {\n  return (int)(((long)channel * (long)brightnessPercent) / 100L);\n}\n\nvoid applyColour() {\n  ledcWrite(RED_PIN, channelDuty(redValue));\n  ledcWrite(GREEN_PIN, channelDuty(greenValue));\n  ledcWrite(BLUE_PIN, channelDuty(blueValue));"},{"type":"code_explanation","body":"Red 255 at brightness 30 becomes duty 76. Red 255 at brightness 48 becomes duty 122. Red 255 at brightness 100 becomes duty 255, and at brightness 0 it becomes duty 0. Green 0 stays duty 0 at every brightness, so a pure red mix does not light the green die."}]$rgbdriver$),
  (16, 4, $rgbdriver$Firmware$rgbdriver$, $rgbdriver$See how BLE accepts colour and brightness$rgbdriver$, $rgbdriver$Excerpt only. This is not a complete sketch. The board advertises one service and two write characteristics.$rgbdriver$, $rgbdriver$The advertised name is Solderi RGB. A Bluetooth Classic serial app will not show this service.$rgbdriver$, $rgbdriver$[{"type":"text","heading":"What this code does","body":"BLEDevice::init starts the BLE stack with the name Solderi RGB. The server owns one service. The colour characteristic can be read or written. The brightness characteristic can be read or written. After a disconnect, startAdvertising runs again so the phone can reconnect. The accepted colour is also written back so a later read shows the text the sketch stored."},{"type":"code","language":"Arduino","filename":"esp32_ble_rgb_controller.ino","libraries":["BLE (ESP32 Arduino core)","LEDC (ESP32 Arduino core)"],"code":"BLEDevice::init(DEVICE_NAME);\n  BLEServer *server = BLEDevice::createServer();\n  server->setCallbacks(new ServerCallbacks());\n  BLEService *service = server->createService(SERVICE_UUID);\n\n  BLECharacteristic *colorCharacteristic = service->createCharacteristic(\n    COLOR_UUID,\n    BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_WRITE | BLECharacteristic::PROPERTY_WRITE_NR\n  );\n  colorCharacteristic->setCallbacks(new ColorCallbacks());\n  colorCharacteristic->setValue(colourText());\n\n  BLECharacteristic *brightnessCharacteristic = service->createCharacteristic(\n    BRIGHTNESS_UUID,\n    BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_WRITE | BLECharacteristic::PROPERTY_WRITE_NR\n  );\n  brightnessCharacteristic->setCallbacks(new BrightnessCallbacks());\n  brightnessCharacteristic->setValue(brightnessText());\n\n  service->start();\n\n  BLEAdvertising *advertising = BLEDevice::getAdvertising();\n  advertising->addServiceUUID(SERVICE_UUID);\n  advertising->setScanResponse(true);\n  BLEDevice::startAdvertising();\n  Serial.println(\"Advertising as Solderi RGB.\");"},{"type":"code_explanation","body":"The only accepted colour is UTF-8 text such as 255,80,0. Each number is 0 to 255. Spaces around the commas are allowed. The only accepted brightness is UTF-8 text from 0 to 100, including 0, 48, and 100. A three-byte colour such as FF 50 00 is rejected. A rejected write is printed and the previous text is put back, so the LED and a later read stay on the last good value. A valid write then calls applyColour."}]$rgbdriver$),
  (17, 4, $rgbdriver$Firmware$rgbdriver$, $rgbdriver$Paste the complete sketch and upload it$rgbdriver$, $rgbdriver$The program below is the whole firmware. Upload it with ESP32 Dev Module selected.$rgbdriver$, $rgbdriver$If the upload times out, hold Boot, press and release EN, then release Boot and try again. That is the DevKitC V4 download-mode sequence.$rgbdriver$, $rgbdriver$[{"type":"code","language":"Arduino","filename":"esp32_ble_rgb_controller.ino","libraries":["BLE (ESP32 Arduino core)","LEDC (ESP32 Arduino core)"],"code":"/*\n * ESP32 Bluetooth RGB LED Controller\n * Board: ESP32 Dev Module\n * LED: 5 mm common-anode RGB, SparkFun COM-10818 lead order\n * DevKit 5V pin -> common anode\n * IO25 -> 1k -> PN2222A base; collector -> 220 ohm -> red cathode\n * IO26 -> 1k -> PN2222A base; collector -> 220 ohm -> green cathode\n * IO27 -> 1k -> PN2222A base; collector -> 220 ohm -> blue cathode\n * Emitters and DevKit GND share the ground rail\n * A higher PWM duty turns the transistor on for longer\n * Phone app: nRF Connect for Mobile\n * One write format: UTF-8 text\n * Colour: 255,80,0\n * Brightness: 0, 48, or 100\n * Arduino-ESP32 3.x: ledcAttach, BLECharacteristic::PROPERTY_WRITE\n */\n\n#include <BLEDevice.h>\n#include <BLEServer.h>\n#include <BLEUtils.h>\n\nconst int RED_PIN = 25;\nconst int GREEN_PIN = 26;\nconst int BLUE_PIN = 27;\nconst int PWM_FREQUENCY_HZ = 5000;\nconst int PWM_RESOLUTION_BITS = 8;\nconst size_t MAX_TEXT_BYTES = 16;\n\nconst char *DEVICE_NAME = \"Solderi RGB\";\nconst char *SERVICE_UUID = \"8c4a2e10-1b6d-4f3a-9e72-5d0c8a1b6e24\";\nconst char *COLOR_UUID = \"8c4a2e11-1b6d-4f3a-9e72-5d0c8a1b6e24\";\nconst char *BRIGHTNESS_UUID = \"8c4a2e12-1b6d-4f3a-9e72-5d0c8a1b6e24\";\n\nint redValue = 255;\nint greenValue = 0;\nint blueValue = 0;\nint brightnessPercent = 30;\n\nbool clientConnected = false;\n\nint channelDuty(int channel) {\n  return (int)(((long)channel * (long)brightnessPercent) / 100L);\n}\n\nvoid applyColour() {\n  ledcWrite(RED_PIN, channelDuty(redValue));\n  ledcWrite(GREEN_PIN, channelDuty(greenValue));\n  ledcWrite(BLUE_PIN, channelDuty(blueValue));\n}\n\nbool digitsOnly(const String &text) {\n  if (text.length() == 0) {\n    return false;\n  }\n  for (int i = 0; i < text.length(); i++) {\n    char letter = text.charAt(i);\n    if (letter < '0' || letter > '9') {\n      return false;\n    }\n  }\n  return true;\n}\n\nbool copyTextPayload(const uint8_t *data, size_t length, String &text) {\n  text = \"\";\n  if (data == nullptr || length == 0 || length > MAX_TEXT_BYTES) {\n    return false;\n  }\n  for (size_t i = 0; i < length; i++) {\n    char letter = (char)data[i];\n    bool allowed = (letter >= '0' && letter <= '9') || letter == ',' || letter == ' ';\n    if (!allowed) {\n      return false;\n    }\n    text += letter;\n  }\n  text.trim();\n  return text.length() > 0;\n}\n\nbool parseColourText(const String &text) {\n  if (text.indexOf(',') < 0) {\n    return false;\n  }\n  int first = text.indexOf(',');\n  int second = text.indexOf(',', first + 1);\n  if (first <= 0 || second <= first + 1 || text.indexOf(',', second + 1) >= 0) {\n    return false;\n  }\n\n  String redText = text.substring(0, first);\n  String greenText = text.substring(first + 1, second);\n  String blueText = text.substring(second + 1);\n  redText.trim();\n  greenText.trim();\n  blueText.trim();\n  if (!digitsOnly(redText) || !digitsOnly(greenText) || !digitsOnly(blueText)) {\n    return false;\n  }\n\n  long red = redText.toInt();\n  long green = greenText.toInt();\n  long blue = blueText.toInt();\n  if (red > 255 || green > 255 || blue > 255) {\n    return false;\n  }\n\n  redValue = (int)red;\n  greenValue = (int)green;\n  blueValue = (int)blue;\n  return true;\n}\n\nbool parseBrightnessText(const String &text) {\n  if (text.indexOf(',') >= 0 || !digitsOnly(text)) {\n    return false;\n  }\n  long value = text.toInt();\n  if (value > 100) {\n    return false;\n  }\n  brightnessPercent = (int)value;\n  return true;\n}\n\nString colourText() {\n  return String(redValue) + \",\" + String(greenValue) + \",\" + String(blueValue);\n}\n\nString brightnessText() {\n  return String(brightnessPercent);\n}\n\nclass ServerCallbacks : public BLEServerCallbacks {\n  void onConnect(BLEServer *server) override {\n    (void)server;\n    clientConnected = true;\n    Serial.println(\"Phone connected.\");\n  }\n\n  void onDisconnect(BLEServer *server) override {\n    (void)server;\n    clientConnected = false;\n    Serial.println(\"Phone disconnected. Advertising again.\");\n    BLEDevice::startAdvertising();\n  }\n};\n\nclass ColorCallbacks : public BLECharacteristicCallbacks {\n  void onWrite(BLECharacteristic *characteristic) override {\n    String text;\n    bool accepted = copyTextPayload(characteristic->getData(), characteristic->getLength(), text) && parseColourText(text);\n    if (!accepted) {\n      characteristic->setValue(colourText());\n      Serial.print(\"Colour rejected: \");\n      Serial.println(text);\n      return;\n    }\n\n    applyColour();\n    characteristic->setValue(colourText());\n    Serial.print(\"Colour \");\n    Serial.println(colourText());\n  }\n};\n\nclass BrightnessCallbacks : public BLECharacteristicCallbacks {\n  void onWrite(BLECharacteristic *characteristic) override {\n    String text;\n    bool accepted = copyTextPayload(characteristic->getData(), characteristic->getLength(), text) && parseBrightnessText(text);\n    if (!accepted) {\n      characteristic->setValue(brightnessText());\n      Serial.print(\"Brightness rejected: \");\n      Serial.println(text);\n      return;\n    }\n\n    applyColour();\n    characteristic->setValue(brightnessText());\n    Serial.print(\"Brightness \");\n    Serial.println(brightnessPercent);\n  }\n};\n\nvoid setup() {\n  Serial.begin(115200);\n  delay(300);\n\n  if (!ledcAttach(RED_PIN, PWM_FREQUENCY_HZ, PWM_RESOLUTION_BITS) ||\n      !ledcAttach(GREEN_PIN, PWM_FREQUENCY_HZ, PWM_RESOLUTION_BITS) ||\n      !ledcAttach(BLUE_PIN, PWM_FREQUENCY_HZ, PWM_RESOLUTION_BITS)) {\n    Serial.println(\"PWM setup failed.\");\n  }\n  applyColour();\n\n  Serial.println(\"ESP32 Bluetooth RGB LED controller\");\n  Serial.println(\"Power-on colour is red at 30 percent brightness.\");\n\n  BLEDevice::init(DEVICE_NAME);\n  BLEServer *server = BLEDevice::createServer();\n  server->setCallbacks(new ServerCallbacks());\n  BLEService *service = server->createService(SERVICE_UUID);\n\n  BLECharacteristic *colorCharacteristic = service->createCharacteristic(\n    COLOR_UUID,\n    BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_WRITE | BLECharacteristic::PROPERTY_WRITE_NR\n  );\n  colorCharacteristic->setCallbacks(new ColorCallbacks());\n  colorCharacteristic->setValue(colourText());\n\n  BLECharacteristic *brightnessCharacteristic = service->createCharacteristic(\n    BRIGHTNESS_UUID,\n    BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_WRITE | BLECharacteristic::PROPERTY_WRITE_NR\n  );\n  brightnessCharacteristic->setCallbacks(new BrightnessCallbacks());\n  brightnessCharacteristic->setValue(brightnessText());\n\n  service->start();\n\n  BLEAdvertising *advertising = BLEDevice::getAdvertising();\n  advertising->addServiceUUID(SERVICE_UUID);\n  advertising->setScanResponse(true);\n  BLEDevice::startAdvertising();\n  Serial.println(\"Advertising as Solderi RGB.\");\n}\n\nvoid loop() {\n  delay(200);\n}\n"},{"type":"text","heading":"Upload","body":"Create a sketch named esp32_ble_rgb_controller and replace its contents with the program above. Do not add BluetoothSerial.h. Click Upload. Wait until the IDE reports the upload is done. Open the Serial Monitor at 115200 baud. Do not change pins 25, 26, or 27 unless you also change the wiring."},{"type":"expected","heading":"What you should observe","body":"The IDE finishes the upload. The Serial Monitor prints “ESP32 Bluetooth RGB LED controller”, “Power-on colour is red at 30 percent brightness.”, and “Advertising as Solderi RGB.” The LED is red and not at full brightness."}]$rgbdriver$),
  (18, 5, $rgbdriver$Phone control$rgbdriver$, $rgbdriver$Install nRF Connect and find Solderi RGB$rgbdriver$, $rgbdriver$Use Nordic nRF Connect for Mobile. It is a BLE GATT app on Android and iOS.$rgbdriver$, $rgbdriver$Turn the phone’s Bluetooth on. This scan does not use the phone’s Wi-Fi.$rgbdriver$, $rgbdriver$[{"type":"text","heading":"Which app","body":"Install nRF Connect for Mobile, published by Nordic Semiconductor. On Android, install it from Google Play. On iPhone or iPad, install it from the App Store; Nordic’s listing is nRF Connect for Mobile, Apple id 1054362403, and the current listing requires a recent iOS. The app scans for Bluetooth Low Energy devices and can write a characteristic. This repository has not installed the app or connected it to a board. Do not use a Bluetooth Classic terminal. Those apps look for a serial-port profile, and this sketch does not advertise one. iOS does not provide that Classic serial profile to ordinary apps."},{"type":"text","heading":"What to do","body":"Open nRF Connect and start a scan. Find the name Solderi RGB. The 128-bit service UUID fills most of the advertising packet, so the name is carried in the scan response. If a row has a blank name, open it and match the service that starts with 8c4a2e10. Connect. You should see a colour characteristic starting with 8c4a2e11 and a brightness characteristic starting with 8c4a2e12. A read of the colour characteristic returns the text 255,0,0 until you write a new colour. The Serial Monitor prints “Phone connected.”"},{"type":"expected","heading":"Expected result","body":"The phone shows Solderi RGB as connected. The LED is still the power-on red, because connecting does not by itself change the colour."}]$rgbdriver$),
  (19, 5, $rgbdriver$Phone control$rgbdriver$, $rgbdriver$Write a colour$rgbdriver$, $rgbdriver$Send 0,0,255 as text. The LED should turn blue and Serial should print that colour.$rgbdriver$, $rgbdriver$On Android, set the value format to Text. On iOS, use the UTF-8 string field. Both have been in nRF Connect since the iOS 1.8.8 text-input update. This session did not tap Send on a phone.$rgbdriver$, $rgbdriver$[{"type":"text","heading":"What to do","body":"Open the colour characteristic that starts with 8c4a2e11. On Android, tap the write icon and set the format to Text. On iOS, choose the UTF-8 string input rather than the hexadecimal byte field. Type 0,0,255. If the app offers Request and Command, either is accepted; Request is the normal write. Send it. Then send 255,80,0 the same way. If the iOS field will only take hex, type the UTF-8 bytes of that same text: 30 2C 30 2C 32 35 35 for 0,0,255, or 32 35 35 2C 38 30 2C 30 for 255,80,0. Do not send FF 50 00. Those three raw bytes are rejected."},{"type":"expected","heading":"Expected result","body":"Serial prints “Colour 0,0,255” and the LED is blue at the current brightness. The next write prints “Colour 255,80,0” and the light becomes orange. A read of the characteristic shows the text the sketch stored. Red may look brighter than green or blue at the same number because its forward voltage is lower, so the same 220 Ω passes more current. All three still have several milliamps available from the 5V pin."}]$rgbdriver$),
  (20, 5, $rgbdriver$Phone control$rgbdriver$, $rgbdriver$Write a brightness$rgbdriver$, $rgbdriver$Brightness is a separate write from 0 to 100. It does not change the stored colour mix.$rgbdriver$, $rgbdriver$Text 100 is full scale for this circuit. Text 0 turns the LED off and leaves the phone connected.$rgbdriver$, $rgbdriver$[{"type":"text","heading":"What to do","body":"Open the brightness characteristic that starts with 8c4a2e12. Use the same Text or UTF-8 field. Write 100, then 48, then 0, then 30. 100 is full scale for this circuit, 48 is a mid value, 0 turns the LED off while the phone stays connected, and 30 returns to the power-on level. If the field will only take hex, type the UTF-8 bytes of those characters: 31 30 30 for 100, 34 38 for 48, 30 for 0, and 33 30 for 30. A single hex byte 30 is the character 0, so it sets brightness 0. It is not decimal 48."},{"type":"expected","heading":"Expected result","body":"Serial prints “Brightness 100”, then “Brightness 48”, then “Brightness 0”, then “Brightness 30”. The colour text stays whatever you wrote last. Disconnecting the phone prints “Phone disconnected. Advertising again.” and the LED stays at the last accepted colour and brightness. Connecting again does not change that colour."},{"type":"warning","body":"Any phone nearby can write these characteristics. The sketch does not ask for a pairing code. Use it as a bench project, not as a lock or a private control."}]$rgbdriver$),
  (21, 6, $rgbdriver$Troubleshooting$rgbdriver$, $rgbdriver$The phone cannot connect$rgbdriver$, $rgbdriver$Fix the app type, the board power, and the advertisement before you change the LED wiring.$rgbdriver$, null, $rgbdriver$[{"type":"troubleshooting","heading":"Bluetooth connection","items":[{"problem":"Solderi RGB never appears in the scan","solution":"Confirm Serial printed “Advertising as Solderi RGB.” If it did not, the upload did not start the BLE server. Use nRF Connect’s BLE scanner, not a Bluetooth Classic device list. Stay within a few metres and scan again. Press EN once to restart advertising."},{"problem":"A serial Bluetooth app cannot find the board","solution":"That app is looking for Bluetooth Classic. This sketch does not call BluetoothSerial. Install nRF Connect for Mobile and scan for Solderi RGB."},{"problem":"The phone connects, then immediately drops","solution":"Keep the Serial Monitor open and read the next line. The sketch advertises again after “Phone disconnected. Advertising again.” Connect once more from nRF Connect. A second phone already connected can make the link look busy."},{"problem":"iOS shows the device but the write button does nothing","solution":"Stay on the connected screen. On Android set the format to Text. On iOS choose the UTF-8 string field. Type 0,0,255 and send a Write Request if the app lists Request and Command. This repository has not completed that write on an iPhone."}]}]$rgbdriver$),
  (22, 6, $rgbdriver$Troubleshooting$rgbdriver$, $rgbdriver$The colour or the wiring is wrong$rgbdriver$, $rgbdriver$Match the Serial colour line to the LED before you rewrite the sketch.$rgbdriver$, $rgbdriver$A swapped cathode looks like the wrong colour even when the write was accepted.$rgbdriver$, $rgbdriver$[{"type":"troubleshooting","heading":"Colours and wiring","items":[{"problem":"Serial prints Colour 0,0,255 but the LED is not blue","solution":"The write worked. IO27 is not reaching the blue base, or the blue cathode is in another row. Trace IO27 through 1k blue to the blue base, then from the blue collector through 220 blue to the blue cathode. The anode must be on the 5V rail and the blue emitter on GND."},{"problem":"The LED stays dark after a successful colour line","solution":"Write brightness 100. A stored brightness of 0 keeps every duty at 0. If it is still dark, the anode is not on the 5V rail, an emitter is not on GND, or the part is not common anode. Stop. Do not move the common lead to GND and do not tie a cathode straight to a GPIO."},{"problem":"One colour stays off while the other two follow the phone","solution":"Check that colour’s 220 Ω resistor, the transistor lead order, and the 1 kΩ base resistor. A collector and emitter swapped, or a base left open, leaves that die dark. Do not bypass the 220 Ω resistor. Green and blue are expected to light from this 5 V path, including when their drop is 3.4 V."},{"problem":"Serial prints Colour rejected","solution":"Send UTF-8 text such as 255,80,0. Words, a trailing comma, a number above 255, or three raw bytes such as FF 50 00 are rejected. Serial prints Colour rejected and the previous colour stays."},{"problem":"One colour stays on at full brightness as soon as USB is plugged in, before upload","solution":"A cathode is connected toward ground without its transistor, or a base is tied to 5V. Unplug USB. Each cathode must reach ground only through its 220 Ω resistor and its transistor. Each GPIO must reach only a 1 kΩ resistor."}]}]$rgbdriver$),
  (23, 7, $rgbdriver$How the light mixes$rgbdriver$, $rgbdriver$PWM, BLE, and RGB mixing$rgbdriver$, $rgbdriver$The phone sends a mix. PWM turns that mix into three pin duties.$rgbdriver$, null, $rgbdriver$[{"type":"text","heading":"PWM","body":"LEDC switches each GPIO on and off at 5000 Hz with 8-bit resolution. The eye sees the average, not the individual pulses. Duty 0 is off. Duty 255 is on for the whole cycle. Brightness scales all three duties together, so 50 percent brightness halves each channel without changing the mix."},{"type":"text","heading":"BLE","body":"Bluetooth Low Energy here is a GATT server. The ESP32 is the peripheral and advertises a name plus a service UUID. The phone is the central. A write is a short value to one characteristic, not a stream of serial bytes. Bluetooth Classic SPP is a different radio profile. This sketch never starts it, which is why a Classic terminal cannot connect, including on phones that only expose BLE to apps."},{"type":"text","heading":"RGB mixing","body":"The three dice sit in one lens. 255,0,0 is red. 0,255,0 is green. 0,0,255 is blue. 255,255,255 turns all three on and looks white or slightly tinted, because red passes more current through the same 220 Ω. 255,80,0 is red plus a little green, which reads as orange. The numbers are not watts. They are fractions of each channel’s current from the 5V pin."}]$rgbdriver$),
  (24, 8, $rgbdriver$Final check$rgbdriver$, $rgbdriver$Final verification checklist$rgbdriver$, $rgbdriver$Walk this list once on the bench. A printed line that you have not seen is still unchecked.$rgbdriver$, null, $rgbdriver$[{"type":"test","heading":"Checklist","body":"The longest lead is the anode and it is on the 5V rail. Left to right, the other leads are the red, green, and blue cathodes, each through its own 220 Ω resistor and PN2222A. IO25, IO26, and IO27 each reach only their own 1 kΩ resistor. The 3V3 header is empty, and no second supply is on the 5V pin. The board is ESP32 Dev Module and the upload finished. Serial shows the power-on red line and “Advertising as Solderi RGB.” nRF Connect connects to that name. Colour text 0,0,255 turns the LED blue and Serial prints Colour 0,0,255. Brightness text 48 changes the level, brightness text 0 turns it off, and brightness text 100 restores it. Disconnecting the phone prints the advertising-again line and leaves the last colour lit."},{"type":"expected","heading":"What you have now","body":"An ESP32 DevKit mixes one common-anode RGB LED from the 5V pin, with GPIO25, GPIO26, and GPIO27 switching PN2222A transistors, and a phone changes that mix with nRF Connect over BLE. The project is still unpublished, and a completed checklist on your bench is the hardware test this repository has not recorded."}]$rgbdriver$)
) as v(sort_order, stage_sort_order, stage_title, title, description, tip, blocks)
where p.slug = '24' and p.title = 'ESP32 Bluetooth RGB LED Controller';

update public.projects
set is_published = false
where slug = '24' and title = 'ESP32 Bluetooth RGB LED Controller';
